            Test("duration descriptions", delegate { Assert(TransferPrompt.Describe(TimeSpan.FromSeconds(0.2))=="about 1 second","sub-second"); Assert(TransferPrompt.Describe(TimeSpan.FromSeconds(45))=="about 45 seconds","seconds"); Assert(TransferPrompt.Describe(TimeSpan.FromSeconds(480))=="about 8 minutes","minutes"); Assert(TransferPrompt.Describe(TimeSpan.FromMinutes(125))=="about 2 hours 5 minutes","hours"); });
            Test("maximum text limit raised to 256M", delegate { PasterConfig ok=new PasterConfig(); ok.MaximumTextCharacters=PasterConfig.MaximumTextLimit; ok.Validate(); PasterConfig tooBig=new PasterConfig(); tooBig.MaximumTextCharacters=PasterConfig.MaximumTextLimit+1; bool rejected=false; try { tooBig.Validate(); } catch(ArgumentOutOfRangeException) { rejected=true; } Assert(rejected,"limit not enforced"); });
            Test("a target that blocks simulated input fails before typing and keeps the capture", delegate { FakePlatform p=new FakePlatform(); p.Clipboard="abc"; p.Blocked=true; TransferCoordinator c=new TransferCoordinator(p,new FakeClock(),new PasterConfig()); List<string> failures=new List<string>(); c.Failed+=failures.Add; Assert(c.Capture(),"capture"); Assert(!c.Transfer(),"blocked target typed"); Assert(p.Units.Count==0,"text sent to a blocked target"); Assert(c.Status.HasCapture && !c.Status.IsTransferring,"state after blocked target"); Assert(failures.Count==1 && failures[0]==TransferCoordinator.BlockedMessage("Target App") && failures[0].Contains("Press Ctrl+V"),"blocked target not reported: "+(failures.Count>0?failures[0]:"")); p.Blocked=false; Assert(c.Transfer() && String.Join("",p.Units.ToArray())=="abc","transfer after unblocking"); });
            Test("only failures the user did not cause are reported", delegate { FakePlatform p=new FakePlatform(); p.Clipboard="ab\ncd"; PasterConfig cfg=new PasterConfig(); cfg.CharactersPerBatch=1; cfg.ConfirmAboveLines=1; TransferCoordinator c=new TransferCoordinator(p,new FakeClock(),cfg); List<string> failures=new List<string>(); c.Failed+=failures.Add;
                p.InterruptAfterUnits=1; Assert(!c.Transfer(),"interruption ignored"); p.InterruptAfterUnits=-1; p.Choice=TransferChoice.Cancel; Assert(!c.Transfer(),"declined prompt typed"); Assert(failures.Count==0,"user-caused stop reported: "+String.Join("|",failures.ToArray()));
                p.Choice=TransferChoice.Start; p.Units.Clear(); p.ChangeAfterFirst=true; Assert(!c.Transfer(),"focus change ignored"); Assert(failures.Count==1 && failures[0].StartsWith("Typing stopped because Other App took the focus"),"focus change not reported: "+(failures.Count>0?failures[0]:""));
                p.ChangeAfterFirst=false; p.Clipboard=null; c.Clear(); Assert(!c.Transfer(),"empty transfer"); Assert(failures.Count==2,"missing text not reported"); c.ReportError("x"); Assert(failures.Count==3 && failures[2]=="x","reported error not raised"); });
            Test("a start delay of 250 ms survives saving and loading", delegate { string path=Path.Combine(Path.GetTempPath(),"paster-test-"+Guid.NewGuid().ToString("N")+".json"); try { PasterConfig cfg=new PasterConfig(); cfg.StartDelayMilliseconds=250; cfg.Save(path); Assert(PasterConfig.Load(path).StartDelayMilliseconds==250 && PasterConfig.LoadOrCreate(path).StartDelayMilliseconds==250,"250 ms rewritten"); } finally { File.Delete(path); } });
            Test("an unusable settings file reports why", delegate { string path=Path.Combine(Path.GetTempPath(),"paster-test-"+Guid.NewGuid().ToString("N")+".json"); try { string error; PasterConfig.LoadOrCreate(path,out error); Assert(error==null,"new file reported: "+error); PasterConfig.LoadOrCreate(path,out error); Assert(error==null,"valid file reported: "+error); File.WriteAllText(path,"{\"charactersPerBatch\":0}",new UTF8Encoding(false)); PasterConfig c=PasterConfig.LoadOrCreate(path,out error); Assert(c.CharactersPerBatch==32,"defaults not used"); Assert(error!=null && error.Contains("Characters per batch must be between 1 and 4096") && !error.Contains("Parameter name"),"error: "+error); } finally { File.Delete(path); } });
            Test("tray icon is off and notifications on by default, both copied with the settings", delegate { PasterConfig a=new PasterConfig(); Assert(!a.ShowTrayIcon && a.ShowNotifications,"defaults"); a.ShowTrayIcon=true; a.ShowNotifications=false; PasterConfig b=new PasterConfig(); b.CopyFrom(a); Assert(a.Clone().ShowTrayIcon && b.ShowTrayIcon && !a.Clone().ShowNotifications && !b.ShowNotifications,"settings not copied"); });
            Test("switching windows yourself stops typing silently and keeps the resume point", delegate { FakePlatform p=new FakePlatform(); p.Clipboard="ab\ncd"; p.ChangeAfterFirst=true; p.RecentInput=true; PasterConfig cfg=new PasterConfig(); cfg.CharactersPerBatch=2; cfg.ConfirmAboveLines=1; cfg.StopOnUserInput=false; TransferCoordinator c=new TransferCoordinator(p,new FakeClock(),cfg); List<string> failures=new List<string>(); c.Failed+=failures.Add; Assert(!c.Transfer(),"switch ignored"); Assert(failures.Count==0,"own window switch reported: "+String.Join("|",failures.ToArray())); Assert(c.Status.LastError==TransferCoordinator.SwitchedWindowMessage,"status: "+c.Status.LastError); Assert(c.Status.ResumeOffset==2,"resume point "+c.Status.ResumeOffset); });
            Test("another program taking the focus is reported with its name and progress", delegate { FakePlatform p=new FakePlatform(); p.Clipboard="ab\ncd"; p.ChangeAfterFirst=true; PasterConfig cfg=new PasterConfig(); cfg.CharactersPerBatch=2; cfg.ConfirmAboveLines=1; TransferCoordinator c=new TransferCoordinator(p,new FakeClock(),cfg); List<string> failures=new List<string>(); c.Failed+=failures.Add; Assert(!c.Transfer(),"focus steal ignored"); Assert(failures.Count==1 && failures[0]=="Typing stopped because Other App took the focus (2 of 5 characters typed). Paste again in the original window to resume.","message: "+(failures.Count>0?failures[0]:"none")); p.Units.Clear(); p.OtherProgram="Target App"; p.ChangeAfterFirst=true; cfg.ConfirmAboveLines=0; failures.Clear(); Assert(!c.Transfer(),"second steal ignored"); Assert(failures.Count==1 && failures[0].StartsWith("Typing stopped because another Target App window took the focus") && !failures[0].Contains("resume"),"same-program message: "+(failures.Count>0?failures[0]:"none")); });
            Test("remote destinations are typed as Unicode characters, local ones as keys", delegate { FakePlatform p=new FakePlatform(); p.Clipboard="Out-Null"; p.Remote=true; TransferCoordinator c=new TransferCoordinator(p,new FakeClock(),new PasterConfig()); Assert(c.Transfer(),"remote transfer"); Assert(p.RemoteFlags.Count>0 && p.RemoteFlags.TrueForAll(r => r),"remote flag missing"); p.RemoteFlags.Clear(); p.Remote=false; Assert(c.Transfer(),"local transfer"); Assert(p.RemoteFlags.Count>0 && p.RemoteFlags.TrueForAll(r => !r),"local transfer flagged remote"); });
            Test("in remote windows keys get their own batches and the characters after them wait", delegate { FakePlatform p=new FakePlatform(); p.Clipboard="ab\ncd\n\nef"; p.Remote=true; PasterConfig cfg=new PasterConfig(); cfg.RemoteCharactersPerSecond=0; FakeClock clock=new FakeClock(); TransferCoordinator c=new TransferCoordinator(p,clock,cfg); Assert(c.Transfer(),"transfer"); Assert(String.Join("|",p.Units.ToArray())=="ab|\n|cd|\n\n|ef","batches: "+String.Join("|",p.Units.ToArray()).Replace("\n","\\n")); Assert(String.Join(",",clock.Sleeps.ConvertAll(s => s.ToString()).ToArray())=="0,2,152,2,152,2","sleeps: "+String.Join(",",clock.Sleeps.ConvertAll(s => s.ToString()).ToArray()));
                p.Units.Clear(); clock.Sleeps.Clear(); p.Remote=false; Assert(c.Transfer(),"local transfer"); Assert(p.Units.Count==1 && clock.Sleeps.TrueForAll(s => s<50),"local text split or paused: "+p.Units.Count);
                p.Units.Clear(); clock.Sleeps.Clear(); p.Remote=true; p.Clipboard="a\n"; p.Sequence++; Assert(c.Transfer(),"trailing line break"); Assert(clock.Sleeps.TrueForAll(s => s<50),"pause without characters after it"); });
            Test("key pauses are counted only where characters follow keys", delegate { string lines="ab\ncd\n\nef\n"; Assert(CodeTyping.CountKeyPauses(lines,0,lines.Length,CodeModeKeys.None)==2,"line breaks"); Assert(CodeTyping.CountKeyPauses("f(x)",0,4,CodeModeKeys.None)==0 && CodeTyping.CountKeyPauses("f(x)",0,4,CodeModeKeys.DeleteAutoClosed)==1,"auto-closed openers"); PasterConfig cfg=new PasterConfig(); Assert(cfg.RemoteKeyPauseMilliseconds==150,"default pause"); cfg.RemoteKeyPauseMilliseconds=1001; bool rejected=false; try { cfg.Validate(); } catch(ArgumentOutOfRangeException) { rejected=true; } Assert(rejected,"pause above 1000 ms accepted"); });
            Test("code mode keeps every line's indentation in an auto-indenting editor with a smart Home", delegate { string code="[CmdletBinding()]\nparam(\n    [switch]$RunTests\n)\n\n$e = 'Stop'\n$root = 1\nif ($x) {\n    $c = 2\n    if ($y) {\n        $d = 3\n    }\n}\n$z = 4"; List<TypedKey> keys=CodeTyping.Expand(code,CodeModeKeys.HomeAfterEnter|CodeModeKeys.DismissSuggestions); string typed=SmartEditor.Type(keys); Assert(SmartEditor.WithoutTrailingSpace(typed)==code,"typed:\n"+typed); string withoutEnd=SmartEditor.Type(keys.FindAll(k => k.Action!=KeyAction.End)); Assert(SmartEditor.WithoutTrailingSpace(withoutEnd).Contains("\n    $root = 1"),"the editor model no longer reproduces the reported indentation: "+withoutEnd); });
            Test("remote code mode applies to remote windows whichever shortcut started the paste", delegate { FakePlatform p=new FakePlatform(); p.Clipboard="a\nb"; p.Remote=true; TransferCoordinator c=new TransferCoordinator(p,new FakeClock(),new PasterConfig()); CodeModeKeys remoteKeys=new PasterConfig().CodeModeKeys; Assert(c.Transfer(CodeModeKeys.None,remoteKeys),"remote transfer"); Assert(p.CodeModes.Count>0 && p.CodeModes.TrueForAll(k => k==remoteKeys),"remote window typed without code mode"); p.CodeModes.Clear(); p.Remote=false; Assert(c.Transfer(CodeModeKeys.None,remoteKeys),"local transfer"); Assert(p.CodeModes.Count>0 && p.CodeModes.TrueForAll(k => k==CodeModeKeys.None),"local window typed with remote code mode"); });
            Test("paste normally first: what Ctrl+V does for each check and clipboard content", delegate {
                Assert(PasteFirstMemory.Decide(PasteCheck.Unknown,ClipboardKind.Text)==PasteAction.TryNormalPaste && PasteFirstMemory.Decide(PasteCheck.Works,ClipboardKind.Text)==PasteAction.TryNormalPaste,"text is always checked again");
                Assert(PasteFirstMemory.Decide(PasteCheck.Blocked,ClipboardKind.Text)==PasteAction.Type && PasteFirstMemory.Decide(PasteCheck.Blocked,ClipboardKind.Other)==PasteAction.Type,"blocked windows always type");
                Assert(PasteFirstMemory.Decide(PasteCheck.Works,ClipboardKind.Other)==PasteAction.PasteNormally && PasteFirstMemory.Decide(PasteCheck.Unknown,ClipboardKind.Other)==PasteAction.Type,"unwatchable content pastes normally only where paste was seen to work");
                foreach (PasteCheck check in new PasteCheck[] { PasteCheck.Unknown, PasteCheck.Works, PasteCheck.Blocked }) Assert(PasteFirstMemory.Decide(check,ClipboardKind.Private)==PasteAction.Type,"private content pasted normally for "+check); });
            Test("paste normally first: per-window memory forgets closed windows", delegate { PasteFirstMemory memory=new PasteFirstMemory(); List<IntPtr> alive=new List<IntPtr> { new IntPtr(1), new IntPtr(2), new IntPtr(3) }; Func<IntPtr,bool> isAlive=alive.Contains;
                Assert(memory.Get(new IntPtr(1),isAlive)==PasteCheck.Unknown,"new window"); memory.Set(new IntPtr(1),PasteCheck.Works,isAlive); memory.Set(new IntPtr(2),PasteCheck.Blocked,isAlive);
                Assert(memory.Get(new IntPtr(1),isAlive)==PasteCheck.Works && memory.Get(new IntPtr(2),isAlive)==PasteCheck.Blocked && memory.Count(PasteCheck.Works)==1 && memory.Count(PasteCheck.Blocked)==1,"remembered");
                alive.Remove(new IntPtr(1)); Assert(memory.Get(new IntPtr(1),isAlive)==PasteCheck.Unknown && memory.Count(PasteCheck.Works)==0,"closed window kept its check");
                alive.Remove(new IntPtr(2)); memory.Set(new IntPtr(3),PasteCheck.Works,isAlive); Assert(memory.Count(PasteCheck.Blocked)==0,"closed window not pruned");
                memory.Clear(); Assert(memory.Count(PasteCheck.Works)==0 && memory.Get(new IntPtr(3),isAlive)==PasteCheck.Unknown,"clear"); });
            Test("paste normally first is opt-in per app, counts as a remote window, and never applies to browsers", delegate { PasterConfig cfg=new PasterConfig();
                Assert(cfg.PasteFirstApps=="" && !cfg.IsPasteFirstApp(@"C:\Windows\System32\mstsc.exe","srv - Remote Desktop Connection") && !cfg.IsPasteFirstApp("RDCMan.exe",null),"not opt-in");
                cfg.PasteFirstApps="mstsc.exe, mRemoteNG"; cfg.TypeOnPasteApps=""; Assert(cfg.IsPasteFirstApp("mstsc.exe","srv - Remote Desktop Connection") && cfg.IsPasteFirstApp(@"C:\Program Files\mRemoteNG\mRemoteNG.exe",null) && !cfg.IsPasteFirstApp("RDCMan.exe",null),"matching");
                Assert(cfg.IsTypeOnPasteApp("mRemoteNG.exe",null),"paste-first app is not a remote window");
                cfg.PasteFirstApps="msedge.exe:Windows App, chrome.exe, firefox"; Assert(!cfg.IsPasteFirstApp("msedge.exe","Windows App") && !cfg.IsPasteFirstApp("chrome.exe","x") && !cfg.IsPasteFirstApp("FIREFOX.EXE","x"),"browser pastes normally first");
                Assert(cfg.IsTypeOnPasteApp("msedge.exe","Windows App"),"browser entry no longer typed");
                string message=PasteFirstMemory.BlockedMessage("Remote Desktop Connection"); Assert(message.Contains("Remote Desktop Connection") && message.Contains("Ctrl+Z") && message.Contains("from now on"),"message: "+message); });
            Test("the paste-first app list is written to the settings file", delegate { string path=Path.Combine(Path.GetTempPath(),"paster-test-"+Guid.NewGuid().ToString("N")+".json"); try { PasterConfig.LoadOrCreate(path); Assert(File.ReadAllText(path).Contains("\"pasteFirstApps\""),"missing"); PasterConfig cfg=new PasterConfig(); cfg.PasteFirstApps="mstsc.exe"; cfg.Save(path); Assert(PasterConfig.Load(path).PasteFirstApps=="mstsc.exe","not kept"); } finally { File.Delete(path); } });
            Console.WriteLine("{0} tests passed", passed); return 0;
        }
    }
